package store.adityastudio.deliverymanage;
import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.os.Bundle;import android.view.Gravity;import android.view.WindowManager;import android.widget.LinearLayout;import android.widget.TextView;
public class DeliveryAlertActivity extends Activity {private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density);}private TextView text(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.WHITE);v.setPadding(0,dp(7),0,dp(7));return v;}private TextView button(String s,int c){TextView v=text(s,16);v.setGravity(Gravity.CENTER);v.setPadding(dp(15),dp(14),dp(15),dp(14));v.setBackgroundColor(c);return v;}@Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);String title=getIntent().getStringExtra("title"),pickup=getIntent().getStringExtra("pickup"),drop=getIntent().getStringExtra("drop"),earning=getIntent().getStringExtra("earning");LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(24),dp(38),dp(24),dp(24));box.setBackgroundColor(Color.rgb(8,18,40));box.addView(text("NEW DELIVERY REQUEST",14));TextView head=text(title==null?"New delivery order":title,25);head.setTextColor(Color.rgb(110,231,183));box.addView(head);box.addView(text("Pickup: "+(pickup==null?"Food shop":pickup),17));box.addView(text("Drop: "+(drop==null?"Customer address":drop),17));TextView money=text("Your earning: Rs "+(earning==null?"0":earning),20);money.setTextColor(Color.rgb(253,230,138));box.addView(money);box.addView(text("Accept करने पर Delivery Manage खुलेगा।",13));LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);actions.setPadding(0,dp(18),0,0);TextView decline=button("Decline",Color.rgb(185,28,28)),accept=button("Accept order",Color.rgb(5,150,105));actions.addView(decline,new LinearLayout.LayoutParams(0,-2,1));actions.addView(accept,new LinearLayout.LayoutParams(0,-2,1));box.addView(actions);decline.setOnClickListener(v->finish());accept.setOnClickListener(v->{Intent app=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);app.putExtra("orderId",getIntent().getStringExtra("orderId"));startActivity(app);finish();});setContentView(box);}}